form.script:
def main(query: str) -> dict:
    q = query or ""

    rules = [
        {
            "id": "R001",
            "keywords": ["不办工作票", "不用工作票", "跳过工作票", "先干后补票", "先处理后补票"],
            "risk_type": "work_permit",
            "reason": "存在绕过工作票或许可流程的意图"
        },
        {
            "id": "R002",
            "keywords": ["短接保护", "退出保护", "屏蔽保护", "强制信号", "解除联锁", "跳过联锁"],
            "risk_type": "protection_interlock",
            "reason": "涉及保护联锁或信号旁路"
        },
        {
            "id": "R003",
            "keywords": ["打开人孔门", "磨煤机人孔门", "煤粉仓", "煤粉系统开孔", "清理积粉"],
            "risk_type": "coal_powder_system",
            "reason": "涉及煤粉系统、人孔门或积粉清理"
        },
        {
            "id": "R004",
            "keywords": ["动火", "焊接", "切割", "明火", "打磨"],
            "risk_type": "hot_work",
            "reason": "涉及动火作业"
        },
        {
            "id": "R005",
            "keywords": ["受限空间", "进入内部", "进入容器", "进入管道", "进入烟道"],
            "risk_type": "confined_space",
            "reason": "涉及受限空间作业"
        },
        {
            "id": "R006",
            "keywords": ["带电", "强送电", "未隔离", "未泄压", "带压"],
            "risk_type": "electrical_operation",
            "reason": "涉及带电、带压或未隔离状态"
        }
    ]

    hit_rules = []
    risk_types = []
    reasons = []

    for rule in rules:
        for kw in rule["keywords"]:
            if kw in q:
                hit_rules.append(rule["id"])
                risk_types.append(rule["risk_type"])
                reasons.append(rule["reason"])
                break

    priority = [
        "protection_interlock",
        "work_permit",
        "coal_powder_system",
        "hot_work",
        "confined_space",
        "electrical_operation"
    ]

    suggested = "general_high_risk"
    for p in priority:
        if p in risk_types:
            suggested = p
            break

    return {
        "rule_hit": len(hit_rules) > 0,
        "hit_rules": hit_rules,
        "suggested_risk_type": suggested,
        "reason": "；".join(sorted(set(reasons))) if reasons else ""
    }

